var modalReturnFocus=null;
function showModal(html){
 var modal=document.getElementById("modal"),body=document.getElementById("modalBody");
 if(modal.hidden)modalReturnFocus=document.activeElement;
 body.innerHTML=html;modal.hidden=false;
 document.getElementById("app").inert=true;document.body.classList.add("modal-open");
 var heading=body.querySelector("h2,h1,h3");
 if(heading){heading.id="modalTitle";modal.setAttribute("aria-labelledby","modalTitle");modal.removeAttribute("aria-label")}
 else{modal.removeAttribute("aria-labelledby");modal.setAttribute("aria-label","操作窗口")}
 body.querySelectorAll(".field").forEach(function(field,index){var input=field.querySelector("input,textarea,select"),label=field.querySelector("label");if(input&&label){if(!input.id)input.id="modalField"+index;label.htmlFor=input.id}});
 var target=body.querySelector("input:not([type=hidden]),textarea")||body.querySelector("button")||document.getElementById("modalClose");target.focus({preventScroll:true});
}
function closeModal(){
 document.getElementById("modal").hidden=true;document.getElementById("app").inert=false;document.body.classList.remove("modal-open");
 if(modalReturnFocus&&modalReturnFocus.isConnected)modalReturnFocus.focus({preventScroll:true});
}
document.addEventListener("keydown",function(event){
 var modal=document.getElementById("modal");if(!modal||modal.hidden)return;
 if(event.key==="Escape"){event.preventDefault();closeModal();return}
 if(event.key!=="Tab")return;
 var items=Array.from(modal.querySelectorAll('button,input,textarea,select,a[href],[tabindex="0"]')).filter(function(el){return !el.disabled&&el.getClientRects().length});
 if(!items.length){event.preventDefault();return}
 var first=items[0],last=items[items.length-1];
 if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}
 else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}
});
