document.getElementById("view").innerHTML=`<section class="welcome-layout"><div class="welcome-story"><span class="welcome-kicker"><i></i> 律衡 · 法律素养学习空间</span><h1>从生活出发，<br>把每一次判断<br><em>变成成长。</em></h1><p>在真实情境里学习，在一次次追问中理解。<br>让法律知识，成为应对生活的底气。</p><div class="welcome-trail"><span>识别问题</span><b>→</b><span>寻找证据</span><b>→</b><span>作出判断</span></div><div class="welcome-art" aria-hidden="true"><div class="welcome-orbit"></div><img src="whale-mascot.png" alt=""><span class="art-note">学会思考<br><b>也学会行动。</b></span><i class="art-star">✦</i></div></div><aside class="welcome-entry"><span class="entry-number">START YOUR JOURNEY / 01</span><h2>选择你的学习空间</h2><p>课堂内外，从这里开始。</p><button class="entry-choice" id="studentEntry"><span class="entry-icon">学</span><span><b>我是学生</b><small>加入班级，与小衡一起探索</small></span><i>↗</i></button><button class="entry-choice teacher-choice" id="teacherEntry"><span class="entry-icon">师</span><span><b>我是教师</b><small>设计任务，看见每一次进步</small></span><i>↗</i></button><div class="entry-divider"></div><a class="entry-library" href="law.html?resource=laws&from=classroom"><span><small>随时翻开，随时发现</small><b>逛逛法律资源馆</b></span><i>↗</i></a><div class="entry-signature"><span>事实 · 证据 · 依据 · 行动</span><b>律衡</b></div></aside></section><section class="project-intro" aria-labelledby="projectTitle">  <header class="intro-heading"><span class="intro-eyebrow">关于律衡 / WHY WE BUILD</span><h2 id="projectTitle">不止答对一道题，<br>更要看见成长的过程。</h2><p>面向高校法治教育的大模型学习过程管理与教学辅助平台。<br>连接教师与学生，让真实的学习证据，成为下一次教学的依据。</p></header>  <div class="intro-purpose"><span class="intro-index">01 / 设计目标</span><div><h3>让知识走进生活，让教学有据可依。</h3><div class="purpose-columns"><p><b>从“记住”到“会用”</b>从兼职欠薪、租房押金到网购纠纷，在熟悉的情境中练习事实判断与证据分析。</p><p><b>从分数到学习过程</b>结合实际作答发现知识薄弱点，让反馈不仅告诉学生结果，也指出改进方向。</p><p><b>从统一讲解到针对性指导</b>辅助教师准备任务、了解学情，让学生围绕自己的薄弱点继续巩固。</p></div></div></div>  <section class="intro-loop" aria-labelledby="loopTitle"><div class="loop-heading"><span class="intro-eyebrow">核心亮点 / 教学闭环</span><h3 id="loopTitle">每一次练习，都有下一步。</h3><p>同一班级 · 同一任务 · 持续反馈</p></div><ol class="loop-steps"><li><span>01</span><b>发布情境</b><small>教师设计学习任务</small></li><li><span>02</span><b>互动练习</b><small>学生作答与提问</small></li><li><span>03</span><b>发现薄弱点</b><small>依据真实作答分析</small></li><li><span>04</span><b>调整教学</b><small>教师开展针对性指导</small></li><li><span>05</span><b>相似题巩固</b><small>换个情境，再练一次</small></li></ol><div class="loop-return">巩固结果回到学习记录，支持下一轮教学与练习 ↺</div></section>  <section class="intro-audience" aria-labelledby="audienceTitle"><header><span class="intro-index">02 / 服务对象</span><h3 id="audienceTitle">课堂两端，<br>彼此相连。</h3><p>主要服务高校学生，以及承担法治教育的教师、思政教师和辅导员。</p></header><div class="audience-lines"><article><span class="audience-symbol" aria-hidden="true">学</span><div><h4>给学生：从疑问出发，学会判断。</h4><p>尤其面向非法律专业学生。通过情境练习、小衡答疑与学习报告，理解知识，找到薄弱点，再针对性练习。</p></div></article><article><span class="audience-symbol" aria-hidden="true">师</span><div><h4>给教师：看见差异，指导更有方向。</h4><p>管理班级、组织任务、查看学习表现，借助大模型辅助出题与学情分析，为教学调整提供参考。</p></div></article></div></section>  <section class="intro-companion" aria-labelledby="companionTitle"><div class="companion-portrait"><img src="whale-mascot.png" alt="小衡鲸鱼学习搭子" loading="lazy"><span>小衡 · 学习搭子</span></div><div class="companion-copy"><span class="intro-index">03 / 大模型如何帮助学习</span><h3 id="companionTitle">需要答案，也需要思考的空间。</h3><div class="companion-modes"><article><span>即问即答 ↗</span><p>解释概念、回应疑问，及时解开学习中的困惑。</p></article><article><span>循循善导 →</span><p>逐步追问，陪你梳理事实、寻找证据、思考处理路径。</p></article></div><p class="companion-footnote">不只陪聊：大模型也参与任务草拟、学情分析与相似题生成。客观题评分和数据统计由程序完成，教师保留审核与教学决策权。</p></div></section>  <div class="intro-principle"><span>有依据的反馈，有边界的辅助。</span><p>分析以已有作答为依据，样本有限不等于能力定论。模型输出仅供学习参考，重要法律问题应核验权威来源或咨询专业人士。</p></div></section>`;
document.getElementById("teacherEntry").onclick=teacherEntry;
