function teacherEntry(){if(!apiBase){saveSession({user:{id:"demo-teacher",role:"teacher",name:"演示教师",username:"demo"},token:"demo"});teacherDashboard();return}showTeacherLogin()}
function authPending(form,label){
 if(form.getAttribute("aria-busy")==="true")return null;
 var error=form.querySelector(".auth-error");if(error)error.remove();
 form.setAttribute("aria-busy","true");var button=form.querySelector(".primary"),original=button.innerHTML,buttons=Array.from(form.querySelectorAll("button")).map(function(b){return[b,b.disabled]});
 buttons.forEach(function(pair){pair[0].disabled=true});button.innerHTML='<span class="auth-pending"><i class="auth-spinner" aria-hidden="true"></i>'+label+'</span>';
 var status=document.createElement("p");status.className="auth-status";status.setAttribute("role","status");status.textContent=label+"，请稍候…";button.after(status);
 var timer=setTimeout(function(){status.textContent="连接较慢，仍在等待响应，请勿重复提交。"},8000);
 return function(){clearTimeout(timer);form.removeAttribute("aria-busy");button.innerHTML=original;buttons.forEach(function(pair){pair[0].disabled=pair[1]});status.remove()};
}
function showTeacherLogin(){showModal('<form class="form" id="loginForm"><h2>教师登录</h2><p>登录后可访问自己的班级、任务和学情数据。</p><div class="field"><label>教师账号</label><input name="username" required minlength="3"></div><div class="field"><label>密码</label><input name="password" type="password" required></div><button class="primary">登录</button><button class="text-btn" type="button" id="registerSwitch">首次使用，注册教师</button></form>');document.getElementById("loginForm").onsubmit=async function(e){e.preventDefault();var finish=authPending(e.target,"正在登录");if(!finish)return;try{var v=Object.fromEntries(new FormData(e.target));var r=await request("/api/auth/login",{method:"POST",body:v});saveSession(r);closeModal();document.getElementById("view").innerHTML='<div class="student-loading" role="status"><span></span><p>登录成功，正在加载班级…</p></div>';await teacherDashboard()}catch(err){authError(e.target,err)}finally{finish()}};document.getElementById("registerSwitch").onclick=showTeacherRegister}
function showTeacherRegister(){showModal('<form class="form" id="registerForm"><h2>注册教师</h2><p>教师注册码由部署者设置，用于防止公开注册。</p><div class="form-grid"><div class="field"><label>姓名</label><input name="name" required></div><div class="field"><label>账号</label><input name="username" required minlength="3"></div></div><div class="field"><label>密码（至少8位）</label><input name="password" type="password" required minlength="8"></div><div class="field"><label>教师注册码</label><input name="setupCode" type="password" required></div><button class="primary">注册并登录</button></form>');document.getElementById("registerForm").onsubmit=async function(e){e.preventDefault();var finish=authPending(e.target,"正在创建账号");if(!finish)return;try{var r=await request("/api/auth/teacher/register",{method:"POST",body:Object.fromEntries(new FormData(e.target))});saveSession(r);closeModal();await teacherDashboard()}catch(err){authError(e.target,err)}finally{finish()}}}
function rememberedStudent(){try{return localStorage.getItem("lvheng_student_account_v1")||""}catch(e){return""}}
async function copyText(value){try{await navigator.clipboard.writeText(value);toast("已复制")}catch(e){var input=document.createElement("textarea");input.value=value;input.style.position="fixed";input.style.opacity="0";document.body.append(input);input.select();var ok=document.execCommand("copy");input.remove();toast(ok?"已复制":"复制未成功，请长按邀请码手动复制")}}
function studentJoinForm(register){register=register===true;var account=rememberedStudent();showModal('<form class="form student-auth" id="joinForm"><span class="auth-kicker">律衡 · 学生空间</span><h2>'+(register?'开启你的学习旅程':'欢迎回来')+'</h2><p>'+(register?'邀请码只在首次注册时填写，之后使用学习账号和密码登录。':'使用学习账号和密码继续，班级关系会自动保留。')+'</p><div class="auth-tabs"><button type="button" id="studentLoginTab" class="'+(!register?'on':'')+'">登录</button><button type="button" id="studentRegisterTab" class="'+(register?'on':'')+'">首次注册</button></div>'+(register?'<div class="field"><label for="studentInvite">班级邀请码</label><input id="studentInvite" name="classCode" maxlength="6" autocapitalize="characters" autocomplete="off" value="'+(!apiBase?'LVT001':'')+'" placeholder="教师提供的6位邀请码" required></div><div class="field"><label for="studentName">姓名或学习昵称</label><input id="studentName" name="name" minlength="2" maxlength="30" autocomplete="nickname" required></div>':'<div class="field"><label for="studentAccount">学习账号</label><input id="studentAccount" name="username" value="'+esc(account)+'" autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="注册后获得的学习账号" required></div>')+'<div class="field"><label for="studentPassword">学习密码</label><input id="studentPassword" name="'+(register?'pin':'password')+'" type="password" minlength="4" maxlength="20" autocomplete="'+(register?'new-password':'current-password')+'" required></div><button class="primary">'+(register?'注册并加入班级':'登录学生空间')+'</button><small class="auth-note">'+(register?'注册成功后会显示你的学习账号，请保存。':'旧账号使用“班级码-姓名或昵称”作为学习账号；此设备会自动记住账号。')+'</small></form>');document.getElementById("studentLoginTab").onclick=function(){studentJoinForm(false)};document.getElementById("studentRegisterTab").onclick=function(){studentJoinForm(true)};document.getElementById("joinForm").onsubmit=async function(e){e.preventDefault();var finish=authPending(e.target,register?"正在创建账号":"正在登录");if(!finish)return;try{var v=Object.fromEntries(new FormData(e.target)),r;if(register){r=await api("join",v)}else if(apiBase){r=await request("/api/auth/login",{method:"POST",body:v});if(r.user.role!=="student")throw Error("请使用学生账号，教师请从教师入口登录")}else{var u=getStore().users.find(function(x){return x.username===v.username.toLowerCase()&&x.pin===v.password});if(!u)throw Error("账号或密码错误");r={user:{id:u.id,role:"student",name:u.name,username:u.username},token:"demo"}}saveSession(r);closeModal();await studentDashboard();if(register)showStudentAccount(true)}catch(err){authError(e.target,err)}finally{finish()}}}
function showStudentAccount(fresh){if(!session||session.user.role!=="student"){studentJoinForm();return}showModal('<div class="form account-sheet"><span class="auth-kicker">'+(fresh?'注册成功 · 班级已绑定':'我的学习账号')+'</span><h2>'+esc(session.user.name)+'</h2><p>以后登录只需下面的学习账号和学习密码，无需再次填写邀请码。换设备也可使用此账号。</p><div class="account-value"><code>'+esc(session.user.username)+'</code><button class="secondary" id="copyStudentAccount">复制账号</button></div><small>请保存账号。学习密码是你注册时设置的密码。</small><button class="primary" id="accountDone">继续学习</button></div>');document.getElementById("copyStudentAccount").onclick=function(){copyText(session.user.username)};document.getElementById("accountDone").onclick=closeModal}

async function teacherDashboard(){try{var classes=(await api("classes")).classes;if(!activeClass&&classes.length)activeClass=classes[0].id;var selected=classes.find(function(c){return c.id===activeClass})||classes[0];var data=selected?await Promise.all([api("tasks",{classId:selected.id}),api("dashboard",{classId:selected.id})]):[{tasks:[]},{stats:{students:0,publishedTasks:0,submissions:0,average:null,abilities:{}},recent:[]}];renderTeacher(classes,selected,data[0].tasks,data[1])}catch(err){toast(err.message);if(/登录/.test(err.message))clearSession()}}
function renderTeacher(classes,selected,tasks,dash){var st=dash.stats,ab=st.abilities||{},recent=dash.recent||[];var h='<div class="dash-head"><div><small>教师工作台 · '+esc(session.user.name)+'</small><h1>我的教学空间</h1></div><div class="dash-actions"><button class="secondary" id="switchStudent">进入学生空间</button><button class="primary" id="newTask" '+(!selected?'disabled':'')+'>＋ 发布新任务</button></div></div><div class="kpis"><div class="kpi"><small>学生人数</small><b>'+st.students+'</b></div><div class="kpi"><small>已发布任务</small><b>'+st.publishedTasks+'</b></div><div class="kpi"><small>有效提交</small><b>'+st.submissions+'</b></div><div class="kpi"><small>班级平均</small><b>'+(st.average===null?'—':st.average)+'</b></div></div><div class="dash-grid"><div><section class="panel"><div class="panel-head"><h2>我的班级</h2><button class="row-btn" id="newClass">＋ 新建班级</button></div><div class="class-list">'+(classes.length?classes.map(function(c){return'<div class="class-item"><button class="class-row '+(selected&&c.id===selected.id?'active':'')+'" data-class="'+c.id+'"><div><b>'+esc(c.name)+'</b><small>'+Number(c.studentCount||0)+' 名学生</small></div></button><div class="class-invite"><code>'+esc(c.code)+'</code><button type="button" data-copy-code="'+esc(c.code)+'" aria-label="复制'+esc(c.name)+'的邀请码"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="8" y="8" width="12" height="12" rx="3"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/></svg>复制邀请码</button></div></div>'}).join(''):'<div class="empty"><b>还没有班级</b>先创建班级，系统会生成学生邀请码。</div>')+'</div></section><section class="panel"><div class="panel-head"><h2>教学任务</h2><small>'+tasks.length+' 个</small></div><div class="task-list">'+(tasks.length?tasks.map(function(t){return taskStudio.row(t)}).join(''):'<div class="empty"><b>还没有任务</b>使用情境模板创建第一项课堂任务。</div>')+'</div></section></div><div><section class="panel"><div class="panel-head"><h2>五维班级能力</h2><small>五个学习维度</small></div><div class="ability-list">'+Object.keys(abilities).map(function(k){var v=ab[k];return'<div class="ability-row"><span>'+abilities[k]+'</span><i><b style="width:'+(v===null?0:v||0)+'%"></b></i><strong>'+(v===null||v===undefined?'—':v)+'</strong></div>'}).join('')+'</div></section><section class="panel"><div class="panel-head"><h2>最近提交</h2></div><div class="recent-list">'+(recent.length?recent.map(function(r){return'<div class="recent-row"><div><b>'+esc(r.studentName)+'</b><small>'+esc(r.taskTitle)+'</small></div><strong>'+r.total+'</strong></div>'}).join(''):'<div class="empty">学生提交后将在这里实时出现。</div>')+'</div></section><button class="text-btn" id="logout">退出当前身份</button></div></div>';document.getElementById("view").innerHTML=h;bindTeacher(selected);var evidence=document.createElement("div");evidence.innerHTML=reportJournal.teacher(dash,tasks);document.querySelector(".dash-grid").before(evidence);evidence.querySelectorAll("[data-teaching-focus]").forEach(function(b){b.onclick=function(){var focus=dash.questionInsights[Number(b.dataset.teachingFocus)];aiTaskForm(selected.id);var goal=document.querySelector("#studioGoal");if(goal)goal.value="围绕「"+focus.label+"」设计巩固任务。原题："+focus.prompt+"。参考解析："+focus.explain+"。请教师审核后发布。"}});mountTeacherPages(classes,selected,evidence)}
function mountTeacherPages(classes,selected,evidence){
 var view=document.getElementById("view"),head=view.querySelector(".dash-head"),grid=view.querySelector(".dash-grid"),panels=grid.querySelectorAll("section.panel"),kpis=view.querySelector(".kpis"),assistant=view.querySelector(".agent-console"),logout=document.getElementById("logout");
 var names={overview:"教学概览",classes:"班级管理",tasks:"教学任务",insights:"学情分析"};
 var shell=document.createElement("div");shell.className="teacher-workspace";
 shell.innerHTML='<aside class="teacher-sidebar"><small>教师工作台</small><nav aria-label="教师页面">'+Object.keys(names).map(function(key){return '<a href="#teacher/'+key+'" data-teacher-page="'+key+'">'+names[key]+'</a>'}).join('')+'</nav><div class="teacher-sidebar-footer"></div></aside><div class="teacher-content"><div class="teacher-context"><label for="teacherClassSelect">当前班级</label><select id="teacherClassSelect" '+(!classes.length?'disabled':'')+'>'+(classes.length?classes.map(function(c){return '<option value="'+esc(c.id)+'" '+(selected&&selected.id===c.id?'selected':'')+'>'+esc(c.name)+'</option>'}).join(''):'<option>请先创建班级</option>')+'</select></div>'+Object.keys(names).map(function(key){return '<section class="teacher-page" id="teacher-'+key+'" aria-label="'+names[key]+'" hidden></section>'}).join('')+'</div>';
 view.append(shell);
 var overview=shell.querySelector("#teacher-overview"),classPage=shell.querySelector("#teacher-classes"),taskPage=shell.querySelector("#teacher-tasks"),insights=shell.querySelector("#teacher-insights");
 overview.append(kpis);
 var welcome=document.createElement("section");welcome.className="panel teacher-next";
 welcome.innerHTML='<small>从这里开始</small><h2>'+(classes.length?'准备好下一堂课':'创建你的第一个班级')+'</h2><p>'+(classes.length?'先准备教学任务，再根据学生提交回顾教学效果。':'创建班级后，将邀请码分享给学生，再发布第一项任务。')+'</p><div><a class="primary" href="#teacher/'+(classes.length?'tasks':'classes')+'">'+(classes.length?'管理教学任务':'前往创建班级')+'</a><a class="secondary" href="#teacher/insights">查看学情</a></div>';
 overview.append(welcome);classPage.append(panels[0]);taskPage.append(assistant,panels[1]);insights.append(evidence,panels[2],panels[3]);
 var insightButton=document.getElementById("aiInsight");insights.prepend(insightButton);
 shell.querySelector(".teacher-sidebar-footer").append(logout);
 var create=document.getElementById("newTask");create.textContent="＋ 创建任务";taskPage.querySelector(".panel-head").append(create);
 grid.remove();
 document.getElementById("teacherClassSelect").onchange=function(){activeClass=this.value;teacherDashboard()};
 shell.querySelectorAll("[data-class]").forEach(function(b){b.setAttribute("aria-pressed",String(!!selected&&b.dataset.class===selected.id))});
 function navigate(focus){
  var key=location.hash.replace("#teacher/","");if(!names[key])key="overview";
  shell.querySelectorAll(".teacher-page").forEach(function(page){page.hidden=page.id!=="teacher-"+key});
  shell.querySelectorAll("[data-teacher-page]").forEach(function(link){if(link.dataset.teacherPage===key)link.setAttribute("aria-current","page");else link.removeAttribute("aria-current")});
  var title=head.querySelector("h1");title.textContent=names[key];title.tabIndex=-1;
  if(focus){title.focus({preventScroll:true});window.scrollTo({top:0,behavior:"instant"})}
 }
 teacherNavigate=navigate;navigate(false);
}
