function createTaskForm(classId){showModal('<div class="form"><h2>创建情境任务</h2><p>选择经过核验的五步模板。教师审核后先保存为草稿，再单独发布。</p><div class="template-list">'+Object.keys(templates).map(function(k,i){return'<button data-template="'+k+'" class="'+(i===0?'on':'')+'"><b>'+templates[k].title+'</b><small>五项能力 · 5个决策环节</small></button>'}).join('')+'</div><div class="field"><label>任务标题</label><input id="taskTitle" value="'+templates.labor.title+'"></div><div class="field"><label>情境描述</label><textarea id="taskScenario" rows="5">'+templates.labor.scenario+'</textarea></div><button class="primary" id="saveTask">保存为草稿</button></div>');var selected="labor";document.querySelectorAll("[data-template]").forEach(function(b){b.onclick=function(){selected=b.dataset.template;document.querySelectorAll("[data-template]").forEach(function(x){x.classList.remove("on")});b.classList.add("on");document.getElementById("taskTitle").value=templates[selected].title;document.getElementById("taskScenario").value=templates[selected].scenario}});document.getElementById("saveTask").onclick=async function(){try{var t=templates[selected];await api("createTask",{classId:classId,title:document.getElementById("taskTitle").value,scenario:document.getElementById("taskScenario").value,content:{questions:t.questions}});closeModal();toast("任务草稿已保存，请确认后发布");teacherDashboard()}catch(e){toast(e.message)}}}
