async function runCoach(input){input=String(input||"").trim();if(input.length<8){toast("请再具体描述一下事情经过");return}var el=document.getElementById("selfResult");el.innerHTML='<div class="agent-loading"><i></i><span>学习智能体正在判断缺失事实与下一步学习支架…</span></div>';try{var r=await api("aiCoach",{message:input}),c=r.coach;el.innerHTML='<section class="coach-result"><div class="coach-head"><span>小衡 · 学习反馈</span><b>'+esc(c.stage||"形成性反馈")+'</b></div><h2>'+esc(c.diagnosis)+'</h2><div class="coach-question"><small>先不公布答案，请你继续思考</small><strong>'+esc(c.nextQuestion)+'</strong></div><div class="self-result-grid"><article><b>待补充事实</b>'+agentList(c.missingFacts)+'</article><article><b>检索范围</b>'+agentList(c.laws)+'</article><article><b>证据提示</b>'+agentList(c.evidence)+'</article><article><b>学习路径</b>'+agentList(c.actions)+'</article></div><p class="agent-note">'+(c.source==="deepseek"?'由小衡提供学习建议，请核验相关依据。':c.source==="fastgpt"?'由小衡提供学习建议，请核验相关依据。':'当前为本地智能体示范。')+' 自主问题不会进入教师看板。</p></section>';el.scrollIntoView({behavior:"smooth",block:"start"})}catch(err){el.innerHTML="";toast(err.message)}}
var originalApi=api;
api=async function(action,arg){
  arg=arg||{};
  if(apiBase&&["createTask","publish","updateTask","closeTask","taskOverview","questionDraft"].includes(action)){
    var capability=await request("/health");
    if(!capability.taskStudio)throw Error("请先在Cloudflare部署最新版Worker，启用任务编辑、截止时间与管理功能");
  }
  var routes={updateTask:["PATCH","/api/tasks/"+arg.id],closeTask:["PATCH","/api/tasks/"+arg.id+"/close"],
    taskOverview:["GET","/api/tasks/"+arg.id+"/overview"],questionDraft:["POST","/api/agent/question-draft"]};
  if(apiBase&&routes[action]){
    try{return await request(routes[action][1],{method:routes[action][0],body:routes[action][0]==="GET"?undefined:arg})}
    catch(e){if(e.message==="Not found")throw Error("后端尚未更新任务工作台接口，请部署最新版Worker");throw e}
  }
  if(!apiBase){
    var s=getStore(),t=s.tasks.find(function(x){return x.id===arg.id});
    if(action==="updateTask"){
      if(!t||t.status!=="draft")throw Error("只能编辑草稿");
      Object.assign(t,{title:arg.title,scenario:arg.scenario,content:arg.content});setStore(s);
      return{task:t};
    }
    if(action==="closeTask"){if(!t||t.status!=="published")throw Error("只能结束进行中的任务");t.status="closed";setStore(s);return{ok:true}}
    if(action==="taskOverview"){
      if(!t)throw Error("任务不存在");
      var rows=s.users.filter(function(u){return u.classId===t.class_id}).map(function(u){
        var sub=s.submissions.find(function(x){return x.task_id===t.id&&x.student_id===u.id});
        return{id:u.id,name:u.name,submissionId:sub&&sub.id,total:sub&&sub.total,submittedAt:sub&&sub.submittedAt,sub:sub};
      });
      var done=rows.filter(function(r){return r.submissionId}),settings=t.content.settings||{};
      return{overview:{task:{id:t.id,title:t.title,status:t.status,settings:settings},students:rows,
        expired:!!settings.dueAt&&Date.parse(settings.dueAt)<=Date.now(),
        questions:t.content.questions.map(function(q,i){return{ability:q.ability,prompt:q.prompt,answered:done.length,correct:done.filter(function(r){return r.sub.details[i].correct}).length}})}};
    }
    if(action==="publish"||action==="submit"){
      if(!t)throw Error("任务不存在");
      if(t.content.settings&&t.content.settings.dueAt&&Date.parse(t.content.settings.dueAt)<=Date.now())throw Error("任务已截止");
      if(action==="publish"&&t.status!=="draft")throw Error("只能发布草稿");
      if(action==="submit"&&t.status!=="published")throw Error("任务已结束");
    }
  }
  var result=await originalApi(action,arg);
  if(action==="tasks"&&!apiBase)result.tasks=result.tasks.map(function(t){return Object.assign({},t,{settings:t.content.settings||{}})});
  if(action==="task"&&!apiBase&&result.task)result.task.dueAt=result.task.content.settings&&result.task.content.settings.dueAt;
  return result;
};
